#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""Fill training feedback placeholders in an HWPX template.

- Reads /root/training_feedback.json
- Opens training_feedback_template.hwpx (a ZIP)
- Replaces {{키}} placeholders in XML text within <hp:p> paragraphs
- Applies specific transforms:
  * 참석자수: digits only
  * 만족도: X.X점 (5.0점 만점)
  * 종합의견: append ' 후속 심화반 검토 요망.'
- Removes stale layout cache elements (linesegarray/lineSegArray/lineseg) from modified paragraphs
- Writes /root/training_feedback_ready.hwpx
"""

from __future__ import annotations

import json
import re
import zipfile
import xml.etree.ElementTree as ET
from typing import Any, Dict, Tuple

TEMPLATE_PATH = "/root/training_feedback_template.hwpx"
JSON_PATH = "/root/training_feedback.json"
OUT_PATH = "/root/training_feedback_ready.hwpx"

HWPML_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"


def _localname(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def _as_str(v: Any) -> str:
    if v is None:
        return ""
    return str(v)


def transform_value(key: str, raw: Any) -> str:
    # Key-based transforms per task contract.
    if key == "참석자수":
        if isinstance(raw, (int, float)):
            # Use as-is for numbers, but make it integral-looking if possible.
            if isinstance(raw, float) and raw.is_integer():
                return str(int(raw))
            return str(raw)
        s = _as_str(raw)
        digits = "".join(re.findall(r"\d+", s))
        return digits if digits else s

    if key == "만족도":
        # Accept numeric or strings like "4.5/5.0".
        if isinstance(raw, (int, float)):
            score = float(raw)
        else:
            s = _as_str(raw)
            m = re.search(r"\d+(?:\.\d+)?", s)
            if not m:
                # Fallback: emit raw but still follow required suffix.
                return f"{s}점 (5.0점 만점)"
            score = float(m.group(0))
        return f"{score:.1f}점 (5.0점 만점)"

    if key == "종합의견":
        base = _as_str(raw).strip()
        if base:
            return base + " 후속 심화반 검토 요망."
        return "후속 심화반 검토 요망."

    return _as_str(raw)


PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def replace_placeholders(text: str, data: Dict[str, Any]) -> Tuple[str, bool]:
    """Replace placeholders in `text` using `data`.

    Returns (new_text, changed).
    """

    changed = False

    def _repl(m: re.Match) -> str:
        nonlocal changed
        key = m.group(1)
        if key not in data:
            # Leave it untouched; validation later will fail loudly.
            return m.group(0)
        changed = True
        return transform_value(key, data[key])

    new_text = PLACEHOLDER_RE.sub(_repl, text)
    # changed indicates at least one placeholder was replaced.
    return new_text, changed


def iter_paragraph_text_nodes(p_elem: ET.Element):
    # HWPX text is typically stored in hp:t elements, but be tolerant.
    for t in p_elem.iter():
        if _localname(t.tag) == "t":
            yield t


def remove_layout_cache_from_paragraph(p_elem: ET.Element) -> None:
    """Remove layout-cache elements under a paragraph.

    Per task contract, remove linesegarray/lineSegArray and similar caches.
    We'll remove any descendant element whose localname matches (case-insensitive)
    'linesegarray' or 'lineseg'.
    """

    # ElementTree doesn't provide getparent, so remove by scanning parents.
    targets = {"linesegarray", "lineseg"}

    def should_remove(tag: str) -> bool:
        ln = _localname(tag)
        folded = ln.lower()
        # normalize common camelCase variants
        folded = folded.replace("_", "")
        return folded in targets

    for parent in list(p_elem.iter()):
        for child in list(parent):
            if should_remove(child.tag):
                parent.remove(child)


def process_xml_bytes(xml_bytes: bytes, data: Dict[str, Any]) -> Tuple[bytes, bool]:
    """Return (new_xml_bytes, modified_anywhere)."""

    # Preserve the hp prefix.
    ET.register_namespace("hp", HWPML_NS)

    root = ET.fromstring(xml_bytes)

    modified_anywhere = False

    # Find all paragraph elements; in HWPX they are hp:p.
    for p in root.iter():
        if _localname(p.tag) != "p":
            continue

        t_nodes = list(iter_paragraph_text_nodes(p))
        if not t_nodes:
            continue

        combined = "".join([(tn.text or "") for tn in t_nodes])
        if "{{" not in combined:
            continue

        replaced, did_replace = replace_placeholders(combined, data)
        if not did_replace:
            continue

        # Write back: keep structure but consolidate text into the first node.
        t_nodes[0].text = replaced
        for tn in t_nodes[1:]:
            tn.text = ""

        remove_layout_cache_from_paragraph(p)
        modified_anywhere = True

    out = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return out, modified_anywhere


def main() -> None:
    with open(JSON_PATH, "r", encoding="utf-8") as f:
        data = json.load(f)

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin:
        infos = zin.infolist()
        # Build output ZIP preserving ZipInfo metadata as much as possible.
        with zipfile.ZipFile(OUT_PATH, "w") as zout:
            for info in infos:
                raw = zin.read(info.filename)

                if info.filename.lower().endswith(".xml"):
                    try:
                        txt = raw.decode("utf-8")
                    except Exception:
                        # Not UTF-8 XML; pass through.
                        zout.writestr(info, raw)
                        continue

                    if "{{" in txt:
                        new_raw, modified = process_xml_bytes(raw, data)
                        zout.writestr(info, new_raw if modified else raw)
                    else:
                        zout.writestr(info, raw)
                else:
                    zout.writestr(info, raw)

    # Verify no placeholders remain.
    with zipfile.ZipFile(OUT_PATH, "r") as zchk:
        offenders = []
        for name in zchk.namelist():
            try:
                content = zchk.read(name).decode("utf-8")
            except Exception:
                continue
            if "{{" in content:
                offenders.append(name)

    if offenders:
        raise SystemExit(f"ERROR: Placeholders still found in: {offenders}")


if __name__ == "__main__":
    main()

